// Outside-in checks, every 5 minutes from CloudWatch Synthetics: what a person
// sees, independent of every internal metric (docs/resilience.md F34).
const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');
const https = require('https');

const HOST = process.env.CAPPY_HOST;

function get(path, expect) {
  return new Promise((resolve, reject) => {
    const started = Date.now();
    https
      .get({ host: HOST, path, headers: { 'User-Agent': 'cappy-canary' } }, (res) => {
        let body = '';
        res.on('data', (c) => (body += c));
        res.on('end', () => {
          log.info(`${path} ${res.statusCode} in ${Date.now() - started} ms`);
          if (res.statusCode !== expect) return reject(new Error(`${path}: ${res.statusCode}, expected ${expect}`));
          resolve(body);
        });
      })
      .on('error', reject);
  });
}

exports.handler = async () => {
  await synthetics.executeStep('web app loads', () => get('/', 200));
  await synthetics.executeStep('categories', () => get('/api/categories', 200));
  await synthetics.executeStep('search answers', async () => {
    const page = JSON.parse(await get('/api/search?q=saw&limit=5', 200));
    if (!Array.isArray(page.items)) throw new Error('search returned no items array');
  });
  await synthetics.executeStep('internal routes stay private', () => get('/api/internal/busy', 404));
  await synthetics.executeStep('bookings need sign-in', () => get('/api/bookings', 401));
};
